}

export interface AsamBatchResult {
    readonly status: 'success' | 'failure' | 'unknown';
    readonly message?: string;
}

export interface AsamBatchVerification {
    /** unsent 仅用于可信证据确认未应用；读到旧数据、读失败或丢响应不能据此释放未决锁。 */
    readonly status: AsamBatchResult['status'] | 'unsent';
    readonly message?: string;
}

